// The service worker: what makes the app open with no network (C-27).
//
// Not built by Vite and not written in TypeScript, because a service worker is
// not part of the app — it is a separate program with its own global scope, its
// own lifecycle and no DOM, and bundling it with the shell it caches invites
// exactly the confusion that makes service workers famous. It is copied into
// the build with two placeholders filled in, by the plugin in `vite.config.ts`.
//
// Hand-written rather than generated by Workbox. What is actually needed here
// is "precache this list, serve it back, drop the last one" — sixty lines, all
// of them visible, against a dependency whose behaviour would have to be taken
// on trust. The same reasoning as ADR 0004 and for the same kind of thing: the
// interesting part of this file is the *policy*, and a policy nobody can read
// is a policy nobody can be sure of.

/**
 * Every file the build emitted, relative to this worker: wherever the app is
 * served from, its files are beside the worker (ADR 0021).
 */
const PRECACHE = __PRECACHE__

/**
 * Name of this build's cache.
 *
 * Derived from the precache list, so a build that emits so much as one
 * different hashed filename lands in a cache of its own and the old one is
 * dropped on activation. That is the whole of "cached and versioned": the wasm
 * bundle's name already carries its hash, and the cache name carries the set.
 */
const CACHE = `pastille-__VERSION__`

self.addEventListener('install', (event) => {
	// `reload` so the install fetches from the network rather than from the HTTP
	// cache: a service worker that precaches a stale index.html serves the old
	// app for ever, and it is the one file whose URL does not change.
	event.waitUntil(
		caches
			.open(CACHE)
			.then((cache) =>
				cache.addAll(PRECACHE.map((path) => new Request(path, { cache: 'reload' }))),
			)
			// Taking over on the next load rather than waiting for every tab to
			// close: there is one tab, it is the app, and an update nobody can
			// reach is not an update.
			.then(() => self.skipWaiting()),
	)
})

self.addEventListener('activate', (event) => {
	event.waitUntil(
		caches
			.keys()
			.then((names) =>
				Promise.all(
					names
						.filter((name) => name.startsWith('pastille-') && name !== CACHE)
						.map((name) => caches.delete(name)),
				),
			)
			.then(() => self.clients.claim()),
	)
})

self.addEventListener('fetch', (event) => {
	const request = event.request
	// Only plain reads of our own origin. A POST is not something to answer from
	// a cache, and nothing on another origin belongs in ours.
	if (request.method !== 'GET') return
	if (new URL(request.url).origin !== self.location.origin) return

	// **Cache first, and deliberately so.** Everything in the precache list is
	// content-addressed by the build — a new build is new filenames — so a hit
	// can never be stale. The exception is the document itself, which keeps the
	// same URL for ever: it is answered from the cache to make the app open with
	// no network at all, and the next install replaces it.
	//
	// A navigation is answered with the app's one page whatever path was asked
	// for, because the shell is a single document and a deep link is still it.
	//
	// Relative to the worker, as every path in the precache list is, so the
	// same worker serves the app at the root of a server or under GitHub
	// Pages' /pastille/ (ADR 0021).
	const lookup = request.mode === 'navigate' ? new URL('index.html', self.location).href : request
	event.respondWith(
		caches.match(lookup).then(
			(cached) =>
				cached ??
				fetch(request).then((response) => {
					// Anything the build did not know about — a circuit opened
					// from somewhere else, a font added later — is kept as it is
					// fetched, so the second visit has it offline too.
					if (response.ok && response.type === 'basic') {
						const copy = response.clone()
						caches.open(CACHE).then((cache) => cache.put(request, copy))
					}
					return response
				}),
		),
	)
})
